"""Integrate measured robustness results; preserve manuscript d and its figures."""
from pathlib import Path
import json,shutil

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'articulo_boletin_geologia_uis_adjunto'
RUN=ROOT/'resultados/robustez_20261011'
R=json.loads((RUN/'verified_summary.json').read_text(encoding='utf-8'))
mesh=R['mesh']['models'];syn=R['synthetics']['experiments'];spatial=R['spatial']['folds'];pooled=R['pooled_spatial']
fmt=lambda x,n=3:f'{x:.{n}f}'.replace('.',',')
s=(OUT/'crear_manuscrito_revision_20261011d.py').read_text(encoding='utf-8')
s=s.replace('Manuscrito_tomografia_Vp_Colombia_UIS_revision_20261011d.docx','Manuscrito_tomografia_Vp_Colombia_UIS_revision_20261011e.docx').replace('auditoria_manuscrito_revision_20261011d.json','auditoria_manuscrito_revision_20261011e.json')
s=s.replace('con ocho barridos configurados','con ocho ciclos de ocho direcciones configurados (64 barridos direccionales)')
method='''heading('3.6 Controles no lineales y espaciales',True)
blocks('Comparamos el cálculo directo en mallas anidadas de 10, 5 y 2,5 km sobre el mismo dominio y seis estaciones, las dos con más lecturas por cada banda de latitud (<4,5°, 4,5–8° y ≥8° N). Los nodos físicos de las estaciones se fijaron en los originales de 10 km para aislar el refinamiento del solucionador; los tiempos se interpolaron en las coordenadas exactas de todos sus eventos. Se mantuvieron ocho barridos y un mismo interpolante trilineal de lentitud para los modelos inicial y final, además de un medio homogéneo de 6 km/s. Antes del cálculo se establecieron umbrales de RMS ≤0,10 s, percentil 95 ≤0,25 s para el cambio 5–2,5 km y reducción del error entre refinamientos. Estos umbrales son criterios numéricos del estudio. La comparación no reinvierte el catálogo en las tres mallas.\n\nGeneramos dos dameros de 40 km con perturbaciones de Vp de ±3 % y ±8 % sobre el perfil inicial, mediante nuevos campos FSM a 5 km y fuentes de evento continuas. Introdujimos ruido gaussiano de 0,05 s, perturbaciones uniformes de catálogo de ±5 km por eje, errores de origen de 0,2 s y estáticas de 0,15 s, con semilla 20261011. La inversión comenzó desde 1D a 10 km, con celdas de 20 km y las mismas tres rondas, cotas, regularización y pesos del experimento real. Recalculó campos y Jacobianos en cada actualización; los datos no proceden del Jacobiano de inversión. La misma familia FSM de primer orden se conserva en generación e inversión. Los umbrales de recuperación fueron correlación ≥0,70, razón de amplitud entre 0,5 y 1,5 y error L2 relativo ≤0,60, calculados sobre las celdas activas; los errores hipocentrales se evaluaron contra las posiciones verdaderas.\n\nLa validación espacial retiró sucesivamente las tres bandas de latitud y excluyó del entrenamiento todos los eventos situados a menos de 20 km horizontales de cualquier evento reservado. Cada partición reinició los modelos 3D y control 1D, y estimó correcciones únicamente con el entrenamiento. La reserva mantuvo posiciones y orígenes fijos; las estaciones ausentes del entrenamiento recibieron corrección cero. No se seleccionaron parámetros usando sus errores. Cada evento participa una sola vez como reserva en el agregado. Esta evaluación es retrospectiva sobre el catálogo ya seleccionado y asociado mediante el perfil original; no constituye una adquisición ciega independiente. El bootstrap de 3000 réplicas remuestrea eventos y no mide incertidumbre entre regiones.')

'''
method_head,method_body=method.split("blocks('",1)
method=method_head+'blocks('+repr(method_body.rsplit("')",1)[0])+')\n\n'
at=s.index("heading('4 Resultados obtenidos')");s=s[:at]+method+s[at:]
s=s.replace('Se mantuvieron ocho barridos y un mismo interpolante trilineal de lentitud', 'Se mantuvo un máximo de ocho ciclos de ocho direcciones, con parada anticipada únicamente si un ciclo no modifica ningún tiempo, y un mismo interpolante trilineal de lentitud')
mesh_names={'homogeneous':'Homogéneo','initial_1d':'Inicial 1D','final_3d':'Final 3D'}
rows_mesh=[[mesh_names[m['model']],fmt(m['delta_10_5']['rms_s']),fmt(m['delta_5_2p5']['rms_s']),fmt(m['p95_abs_5_2p5_s']),fmt(m['apparent_order'],2),'Sí' if m['passes_frozen_gate'] else 'No'] for m in mesh]
rows_syn=[['±'+str(round(100*r['amplitude_fraction']))+' %',fmt(r['correlation']),fmt(r['least_squares_amplitude_ratio']),fmt(r['relative_l2_error']),fmt(r['hypocenter_3d_rmse_km'],2),'Sí' if r['passes_gate'] else 'No'] for r in syn]
rows_space=[]
for name,r in zip(['Sur','Centro','Norte'],spatial):
    b=r['paired_bootstrap'];rows_space.append([name,str(r['train_events']),str(r['holdout_events']),fmt(r['control_1d']['rms_s']),fmt(r['model_3d']['rms_s']),fmt(b['delta_rms_3d_minus_1d_s'])+' ['+fmt(b['ci95_s'][0])+'; '+fmt(b['ci95_s'][1])+']'])
passes_mesh=sum(m['passes_frozen_gate'] for m in mesh);passes_syn=sum(r['passes_gate'] for r in syn)
results="heading('4.7 Convergencia y validación no lineal',True)\n"
results+='table('+repr('Tabla 7. Diferencias de tiempos entre mallas sobre fuentes y modelos físicos fijos.')+','+repr(['Modelo','RMS 10–5 (s)','RMS 5–2,5 (s)','P95 5–2,5 (s)','Orden aparente','Cumple'])+','+repr(rows_mesh)+',[3.0,2.6,2.6,2.6,2.65,2.6])\n'
text_mesh=f'El refinamiento cumple los umbrales predefinidos en {passes_mesh} de los tres medios (Tabla 7). La comparación incluye {mesh[0]["picks"]} tiempos por medio. Las diferencias disminuyen '+('en todos los medios.' if all(m['decreasing_error'] for m in mesh) else 'con comportamiento distinto según el medio.')+' El orden reportado es aparente, calculado con tres niveles de malla, y no demuestra por sí solo que se haya alcanzado el régimen asintótico. El error analítico del medio homogéneo se conserva en el suplemento. La precisión de un refinamiento del cálculo directo no implica convergencia de la solución inversa ni corrige las elevaciones o la curvatura.'
results+='blocks('+repr(text_mesh)+')\n'
results+='table('+repr('Tabla 8. Recuperación de dameros generados a 5 km e invertidos a 10 km con relocalización.')+','+repr(['Amplitud Vp','Correlación','Razón amplitud','Error L2 relativo','RMS ubicación (km)','Cumple'])+','+repr(rows_syn)+',[2.35,2.5,2.9,2.65,3.25,2.4])\n'
text_syn=f'La recuperación no lineal cumple los criterios predefinidos en {passes_syn} de los dos escenarios (Tabla 8). La razón de amplitud corresponde a la pendiente de mínimos cuadrados entre anomalías impuestas y recuperadas, agregadas en las mismas celdas activas. La relocalización y las estáticas permanecen libres en el entrenamiento. El escenario de ±8 % contiene velocidades verdaderas de hasta 8,94 km/s, que sobrepasan la cota de inversión de 8,8 km/s en una parte del volumen; sus amplitudes están restringidas también por ese límite. El ensayo de ±3 % permite examinar la recuperación sin ese excedente. Los datos se generaron en otra malla, aunque ambos solucionadores comparten el esquema de primer orden. Las imágenes y los residuos individuales acompañan las métricas.'
text_syn+=' Las anomalías verdaderas se muestrean en los nodos comunes de 10 km antes de promediarlas a 20 km; los bordes físicos del damero pueden cruzar esas celdas. El control algebraico suplementario comprueba que el promedio de referencia puede representarse mediante una perturbación de lentitud por celda, sin utilizar datos de tiempos. La métrica evalúa ese objetivo agregado, no recuperación punto a punto de todos los detalles de la malla generadora.'
results+='blocks('+repr(text_syn)+')\n'
results+='table('+repr('Tabla 9. Reserva por regiones con margen horizontal de 20 km. Δ es RMS 3D menos control 1D, con IC95 pareado por eventos.')+','+repr(['Región','Entrena','Reserva','RMS 1D (s)','RMS 3D (s)','Δ e IC95 (s)'])+','+repr(rows_space)+',[2.0,2.1,2.1,2.2,2.2,5.45])\n'
b=pooled['bootstrap']
text_space=f'Las particiones excluyen adicionalmente {spatial[0]["buffer_excluded_events"]}, {spatial[1]["buffer_excluded_events"]} y {spatial[2]["buffer_excluded_events"]} eventos del entrenamiento, respectivamente. La distancia horizontal mínima entrenamiento–reserva se comprobó directamente en cada partición. El agregado de {pooled["events"]} eventos y {pooled["picks"]} tiempos P obtiene RMS de {fmt(pooled["control_1d"]["rms_s"])} s para el control 1D y {fmt(pooled["model_3d"]["rms_s"])} s para el 3D. La diferencia agregada es {fmt(b["delta_rms_3d_minus_1d_s"])} s, con intervalo del 95 % [{fmt(b["ci95_s"][0])}; {fmt(b["ci95_s"][1])}] s. La heterogeneidad de desempeño entre regiones se interpreta junto con la cobertura de cada entrenamiento. Este contraste mide extrapolación hacia regiones retiradas; no reemplaza la reserva aleatoria ni una validación tectónica independiente.'
results+='blocks('+repr(text_space)+')\n'
at=s.index("heading('5 Discusión')");s=s[:at]+results+'\n'+s[at:]
s=s.replace('Una prueba no lineal con hipocentros continuos, pesos de lectura calibrados, un perfil 1D regional ajustado y una partición espacial permitiría evaluar cuánto de la heterogeneidad persiste al reducir esos errores.', 'Los controles no lineales y espaciales de la sección 4.7 evalúan ahora recuperación y extrapolación. La inversión mantiene búsqueda hipocentral discreta; pesos de lectura calibrados y un perfil 1D regional ajustado requieren evaluación adicional.')
s=s.replace('Se conserva una interpretación geométrica exploratoria, pendiente de convergencia de malla, pruebas sintéticas no lineales y contrastes regionales independientes.', 'Se conserva una interpretación geométrica exploratoria, cuyo alcance se evalúa con los controles de malla, sintéticos y reserva espacial realizados; sigue pendiente el contraste cuantitativo con modelos regionales independientes.')
s=s.replace('La saturación y las bandas de los cortes requieren controles de convergencia de malla y regularización antes de interpretar amplitudes.', 'La saturación y las bandas de los cortes deben interpretarse junto con los resultados de convergencia directa y recuperación no lineal de la sección 4.7; las restricciones numéricas no se eliminan al realizar esos controles.')
discussion=f'Las reservas por regiones amplían el contraste predictivo: el agregado favorece al control 1D, con RMS de {fmt(pooled["control_1d"]["rms_s"])} frente a {fmt(pooled["model_3d"]["rms_s"])} s. La precisión del cálculo directo es una limitación distinta de la consistencia del Jacobiano. Las diferencias entre refinamientos no se trasladan directamente a una cota del RMS observado, pero muestran que el operador permanece sensible al espaciamiento. Los sintéticos incluyen fuentes perturbadas y reajuste de orígenes y estaciones; su ruido de lectura de 0,05 s es un escenario favorable, no una incertidumbre calibrada del catálogo real. La recuperación debe evaluarse con sus amplitudes y posiciones verdaderas, junto con el RMS, para distinguir ajuste de observaciones e identificación de estructura.'
at=s.index("heading('5.2 Alcance")
s=s[:at]+'blocks('+repr(discussion)+')\n\n'+s[at:]
# Mention the completed controls briefly in both abstracts without exceeding 300 words.
old='Los RMS verticales sobre los controles fueron 18,79 y 28,32 km, mientras que los contrastes con profundidades de catálogo reservadas fueron 32,03 y 20,03 km. Las áreas interpoladas representan 39,28 % y 36,62 % de ambas superficies.'
new=f'Comprobamos mallas de 10, 5 y 2,5 km, dameros no lineales de ±3 % y ±8 %, y reservas regionales con margen de 20 km. El RMS espacial es {fmt(pooled["control_1d"]["rms_s"])} s para 1D y {fmt(pooled["model_3d"]["rms_s"])} s para 3D.'
if passes_mesh<3:new+=' El cambio de malla del 3D alcanza RMS de '+fmt(next(m for m in mesh if m['model']=='final_3d')['delta_5_2p5']['rms_s'])+' s, superior al umbral de 0,10 s.'
s=s.replace(old,new)
old_en='Vertical fitting RMS values were 18.79 and 28.32 km, whereas comparisons with withheld catalog depths yielded 32.03 and 20.03 km. Interpolated areas represent 39.28% and 36.62% of the surfaces.'
new_en=f'Controls include 10, 5 and 2.5 km grids, nonlinear ±3% and ±8% checkerboards, and regional holdouts with 20 km buffers. Pooled spatial RMS is {pooled["control_1d"]["rms_s"]:.3f} s for 1D and {pooled["model_3d"]["rms_s"]:.3f} s for 3D.'
if passes_mesh<3:new_en+=f" The 3D refinement RMS of {next(m for m in mesh if m['model']=='final_3d')['delta_5_2p5']['rms_s']:.3f} s exceeds the adopted 0.10 s tolerance."
s=s.replace(old_en,new_en)
conclusion=f'La evaluación de robustez obtiene cumplimiento de la tolerancia de refinamiento directo en {passes_mesh} de tres medios y de los criterios de recuperación en {passes_syn} de dos dameros. El RMS de reserva espacial agregado es {fmt(pooled["control_1d"]["rms_s"])} s con 1D y {fmt(pooled["model_3d"]["rms_s"])} s con 3D. Estos resultados establecen el alcance numérico y predictivo del experimento. La interpretación de amplitudes e interfaces debe condicionarse a su precisión y recuperación, además de la distribución de apoyo geométrico.'
at=s.index("heading('7 Agradecimientos')");s=s[:at]+'blocks('+repr(conclusion)+')\n\n'+s[at:]
at=s.index("heading('9 Declaraciones")
links="q=p('Controles de robustez: ');link(q,'informe y métricas de malla, sintéticos y reserva espacial','suplementos/robustez_20261011/Informe_robustez_20261011.md')\n"
for n,label in [('Figura_S3_convergencia.png','convergencia directa'),('Figura_S4_sinteticos.png','recuperación sintética no lineal'),('Figura_S5_validacion_espacial.png','reserva espacial')]:links+=f"q=p({label!r}+': ');link(q,'abrir figura suplementaria',{'suplementos/robustez_20261011/figures/'+n!r})\n"
s=s[:at]+links+s[at:]
(OUT/'crear_manuscrito_revision_20261011e.py').write_text(s,encoding='utf-8')
supp=OUT/'suplementos/robustez_20261011';supp.mkdir(exist_ok=True)
for f in RUN.rglob('*'):
    if not f.is_file() or f.suffix not in ['.json','.csv','.md','.png','.py','.npz'] or any('fields' in part or 'isolated' in part for part in f.relative_to(RUN).parts):continue
    dest=supp/f.relative_to(RUN);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(f,dest)
scripts=supp/'scripts';scripts.mkdir(exist_ok=True)
for name in ['robustez_20261011.py','convergencia_malla_20261011.py','sinteticos_no_lineales_20261011.py','sintetico_por_escenario_20261011.py','fsm_equivalente_20261011.py','precalcular_sintetico_08_20261011.py','reutilizar_cache_identica_20261011.py','resumir_robustez_20261011.py','preparar_manuscrito_robustez_20261011e.py','reproducir_controles_20261011.py']:shutil.copy2(ROOT/'codigos'/name,scripts/name)
print(OUT/'crear_manuscrito_revision_20261011e.py')
